def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        version_part, _, _ = v.partition('+')

        # Split by '-' to separate pre-release
        if '-' in version_part:
            core_part, _, prerelease = version_part.partition('-')
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)
        # Versions with pre-release come before versions without
        # So if no pre-release, we use a special value that sorts after any pre-release
        if not prerelease:
            prerelease_key = (1,)  # Sorts after (0, ...)
        else:
            prerelease_key = (0, tuple(prerelease))

        return (major, minor, patch, prerelease_key, index)

    indexed = list(enumerate(versions))
    sorted_indexed = sorted(indexed, key=sort_key)
    return [version for _, version in sorted_indexed]

